ext", "text": "填空题看上下文的衔接"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "语句表达约占言语理解的15%。排序题找首句，填空题看衔接，推断题看尾句。"}]}]}]}$$ AS jsonb), NULL, '言语理解-语句表达概述的核心知识点和解题方法。', category_node.id, CAST('["言语理解", "语句表达概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_sentence_expression", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
